DISC = '<p class="disc">This article is for information only and does not replace advice from an accountant or a lawyer: rules and rates change, so always check your own situation.</p>'

POSTS = [
 dict(it="cin-cir-affitti-brevi-sicilia", en="cin-cir-short-term-rentals-sicily", img="/img/p/pantano-2.webp", mins=6,
  title="CIN and CIR: the rules for short-term rentals in Sicily",
  desc="What the national CIN and the regional CIR are, where to display them, which safety devices you need and what fines you risk. A practical guide for owners in Sicily.",
  body='''<p class="lead">If you rent an apartment to tourists in Sicily, you need two codes: the <strong>CIN</strong> (national) and the <strong>CIR</strong> (regional). Without them your listing is not compliant, and fines can reach several thousand euros. Here is what you need, step by step.</p><h2>The CIN: national identification code</h2><p>The CIN was introduced by art. 13-ter of Decree-Law 145/2023 and is requested online through the <strong>BDSR</strong>, the Ministry of Tourism’s national database of accommodation. It applies to:</p><ul><li>residential properties rented out for tourism;</li><li>units let as <strong>short-term rentals</strong> (up to 30 days);</li><li>hotels and other accommodation businesses.</li></ul><p>The code must be <strong>shown in every online listing</strong> (Airbnb, Booking.com, your own website, social media) and <strong>displayed outside the building</strong>.</p><h3>Safety: what you need to obtain it</h3><p>To get the CIN, the property must meet the required safety standards: <strong>working gas and carbon monoxide detectors</strong> and <strong>compliant portable fire extinguishers</strong>, placed where they are easy to reach. The cost is modest, but it has to be done before you publish.</p><h3>Fines</h3><table><tr><th>Violation</th><th>Fine</th></tr><tr><td>Listing published without a CIN, or CIN never requested</td><td>€800 to €8,000 per unit</td></tr><tr><td>CIN not displayed outside the building</td><td>€500 to €5,000</td></tr><tr><td>No gas/CO detectors or extinguishers (business operators)</td><td>€600 to €6,000</td></tr></table><h2>The CIR: Sicily’s regional identification code</h2><p>The Sicilian Region introduced the CIR for all accommodation businesses and for tourist lets of less than 30 days, <strong>holiday homes included</strong>. You get it by registering the property on the regional tourism data platform (Turist@t).</p><p>The CIR must also appear <strong>next to the property name</strong> in listings, advertising and bookings, on every channel. The fine for not displaying it ranges from €500 to €5,000.</p><h2>Other obligations not to forget</h2><ul><li><strong>Reporting guests to the police</strong> (Alloggiati Web portal) within 24 hours of arrival.</li><li><strong>Reporting statistics</strong> on arrivals and overnight stays to the Region.</li><li><strong>Tourist tax</strong>, where the municipality applies it: it must be collected and paid according to local rules.</li><li><strong>Tax return</strong>: rental income must be declared, and the property’s CIN must be stated in the return too.</li></ul><h2>Quick checklist</h2><ol><li>Install gas/CO detectors and a fire extinguisher.</li><li>Register the property on the regional platform and obtain the CIR.</li><li>Request the CIN through the BDSR.</li><li>Add the CIN and CIR to every listing and display the CIN outside.</li><li>Set up Alloggiati Web and organise tourist tax collection.</li></ol>''' + DISC + '''<div class="srcs"><h4>Sources (in Italian)</h4><ul><li><a href="https://chekin.com/it/blog/affitti-brevi-senza-cin/" target="_blank" rel="noopener">Chekin — Short-term rentals without a CIN: fines and obligations (updated October 2026)</a></li><li><a href="https://www.fiscoetasse.com/domande-e-risposte/12574-cin-affitti-brevi-quali-sono-le-sanzioni-per-gli-inadempienti.html" target="_blank" rel="noopener">Fisco e Tasse — CIN for short-term rentals: the fines</a></li><li><a href="https://www.fiscoetasse.com/new-rassegna-stampa/1908-cin-obbligatorio-nel-730-dove-indicarlo-e-cosa-rischia-chi-lo-omette.html" target="_blank" rel="noopener">Fisco e Tasse — CIN required in the 730 tax return: where to enter it</a></li><li><a href="https://www.regione.sicilia.it/la-regione-informa/turismo-arriva-cir-strutture-ricettive-l-assessore-messina-basta-abusivismo" target="_blank" rel="noopener">Sicilian Region — Tourism: the CIR arrives for accommodation</a></li></ul></div>'''),

 dict(it="tasse-affitti-brevi-2026-cedolare-secca", en="short-term-rental-tax-italy-2026", img="/img/p/kleos-3.webp", mins=5,
  title="Short-term rental tax in Italy in 2026: the 21% and 26% flat tax",
  desc="How short-term rentals are taxed in Italy in 2026: 21% flat tax on the first property, 26% on the second, VAT number from the third. Examples and what to know.",
  body='''<p class="lead">Italy’s 2026 Budget Law confirmed the <strong>“two-speed” flat tax (cedolare secca)</strong> on short-term rentals and lowered the threshold above which renting counts as a business. Here is what changes if you rent out one or more homes.</p><h2>The rules in brief</h2><table><tr><th>Properties let short-term</th><th>Tax regime</th></tr><tr><td>1st property (you choose which)</td><td>flat tax <strong>21%</strong></td></tr><tr><td>2nd property</td><td>flat tax <strong>26%</strong></td></tr><tr><td>From the 3rd property on</td><td>business activity: you need a <strong>VAT number (partita IVA)</strong></td></tr></table><p>The legal basis is art. 1, paragraph 17, of Law no. 199/2025 (2026 Budget Law). Previously, renting was presumed to be a business from the fifth property; now the third is enough.</p><h2>When the flat tax applies</h2><p>The short-term rental flat tax covers contracts of <strong>up to 30 days</strong> between private individuals, outside any business activity, for residential properties in Italy (cadastral categories A1 to A11, excluding A10) and their appurtenances. Services such as <strong>linen and cleaning</strong> are included in the rent.</p><p>The flat tax is optional: alternatively, the rent is added to your income and taxed under ordinary IRPEF rates. For medium to high incomes the flat tax is usually better value, but it should be assessed case by case.</p><h2>A worked example</h2><p>Two apartments each earning €20,000 a year, under the flat tax:</p><ul><li>Apartment A (chosen as the first): 20,000 × 21% = <strong>€4,200</strong></li><li>Apartment B: 20,000 × 26% = <strong>€5,200</strong></li></ul><p>So choosing the higher-earning home as your “first property” saves money: 5 percentage points on your most profitable property.</p><h2>The role of platforms and intermediaries</h2><p>When an intermediary (a platform or a property manager) collects the rent on the owner’s behalf, it applies a <strong>withholding tax on account</strong> and issues a certificate for it: in your tax return it is deducted from the tax due. Always keep the certificates you receive.</p><h2>What to do now</h2><ol><li>Count how many properties you actually let short-term.</li><li>If you have two, decide with your accountant which one to declare at 21%.</li><li>If you have three or more, plan ahead for opening a VAT number and choosing the right regime.</li><li>Keep income, commissions and expenses in order: you need them both for your tax return and to understand your real returns.</li></ol>''' + DISC + '''<div class="srcs"><h4>Sources (in Italian)</h4><ul><li><a href="https://www.informazionefiscale.it/affitti-brevi-2026-cosa-cambia-cedolare-secca-partita-iva" target="_blank" rel="noopener">Informazione Fiscale — Short-term rentals 2026: what changes (April 2026)</a></li><li><a href="https://www.partitaiva.it/affitti-brevi-cedolare-secca/" target="_blank" rel="noopener">PartitaIVA.it — Two-speed flat tax, stricter rules from the third property</a></li><li><a href="https://ntplusfisco.ilsole24ore.com/art/affitti-brevi-cedolare-26percento-e-attivita-d-impresa-ora-tre-alloggi-come-gestire-partita-iva-AIFRCRcB" target="_blank" rel="noopener">NT+ Fisco (Il Sole 24 Ore) — 26% flat tax and business activity from three homes</a></li></ul></div>'''),

 dict(it="quanto-si-guadagna-affitto-breve-catania", en="short-term-rental-income-catania", img="/img/p/pantano-1.webp", mins=6,
  title="How much can you earn from a short-term rental in Catania?",
  desc="Real data on Catania’s short-term rental market (average nightly rate, occupancy, revenue) and a worked example from gross to net.",
  body='''<p class="lead">“How much could I earn if I put my home on Airbnb?” It is the question we hear most. The honest answer: it depends, but market data gives a good starting point. And the gap between gross and net is bigger than most people think.</p><h2>Catania’s market in numbers</h2><p>According to Airbtics data on Airbnb listings in Catania (September 2025 – August 2026):</p><table><tr><th>Indicator</th><th>Value</th></tr><tr><td>Average annual revenue per listing</td><td>about <strong>€21,000</strong></td></tr><tr><td>Average daily rate (ADR)</td><td><strong>€87</strong></td></tr><tr><td>Occupancy rate (median)</td><td><strong>65%</strong></td></tr><tr><td>Active listings (October 2026)</td><td>about <strong>3,290</strong></td></tr><tr><td>Strongest / weakest month</td><td>September / January</td></tr></table><p>These are averages: a well-located one-bedroom near the Cathedral, with good photos and high ratings, can do much better; an outlying property with a neglected listing, much worse.</p><h2>From gross to net: an example</h2><p>Take an apartment earning €21,000 gross in a year. The expense figures are <strong>indicative</strong>, only to show the reasoning:</p><table><tr><th>Item</th><th>Amount</th></tr><tr><td>Gross revenue</td><td>€21,000</td></tr><tr><td>Airbnb commission (15.5%)</td><td>− €3,255</td></tr><tr><td>Cleaning and laundry (e.g. 80 stays × €35)</td><td>− €2,800</td></tr><tr><td>Utilities, internet, consumables (estimate)</td><td>− €1,800</td></tr><tr><td>21% flat tax on gross</td><td>− €4,410</td></tr><tr><td><strong>Net before maintenance and management</strong></td><td><strong>≈ €8,700</strong></td></tr></table><p>If you hand management to a co-host, their commission also comes off. On the other hand, professional management usually <strong>raises both the average rate and occupancy</strong>: a few euros more per night and a few extra full weeks change the result more than any saving on expenses.</p><h2>The levers that make the difference</h2><ul><li><strong>Dynamic pricing</strong>: different rates by season, events (Sant’Agata, summer, long weekends) and booking lead time.</li><li><strong>Photos and listing</strong>: the first photo and the title decide the click.</li><li><strong>Reviews</strong>: high ratings improve your ranking in search results and your booking rate.</li><li><strong>Multiple channels</strong>: Airbnb, Booking.com and direct bookings reduce empty periods.</li><li><strong>Low season</strong>: mid-term stays for workers and students can fill January and February.</li></ul><h2>Want an estimate for your property?</h2><p>Every home is different. We offer a free assessment of your property’s potential, with a realistic revenue estimate based on location, type and amenities.</p>''' + DISC + '''<div class="srcs"><h4>Sources</h4><ul><li><a href="https://airbtics.com/annual-airbnb-revenue-in-catania-sicilia-italy-it" target="_blank" rel="noopener">Airbtics — Airbnb revenue in Catania (data September 2025 – August 2026)</a></li><li><a href="https://www.smoobu.com/it/blog/aumento-costi-singoli-host-airbnb/" target="_blank" rel="noopener">Smoobu — Airbnb’s single 15.5% host fee (in Italian)</a></li></ul></div>'''),

 dict(it="cosa-fa-un-co-host-quanto-costa", en="what-does-a-co-host-do-cost", img="/img/p/villa-2.webp", mins=5,
  title="What does a co-host do, and how much does it cost?",
  desc="What a short-term rental co-host really does, typical commissions (10–30%) and what to check in the contract before handing over your home.",
  body='''<p class="lead">Short-term renting pays, but it is a job: messages at all hours, check-ins, cleaning, prices to update, reviews to manage. A <strong>co-host</strong> takes care of it for you. Here is what they do and what it costs.</p><h2>What a co-host does</h2><ul><li><strong>Listing</strong>: photos, title, descriptions in several languages, publishing on Airbnb, Booking.com and other channels.</li><li><strong>Pricing</strong>: dynamic rates updated for season, events and demand.</li><li><strong>Guests</strong>: quick replies, instructions, check-in (including self check-in), support during the stay.</li><li><strong>Cleaning and linen</strong>: coordinating the teams and checking quality between guests.</li><li><strong>Maintenance</strong>: small repairs and trusted technicians.</li><li><strong>Paperwork</strong>: help with CIN and CIR, Alloggiati Web reporting, tourist tax, regular reports.</li></ul><h2>How much it costs: typical commissions</h2><table><tr><th>Service level</th><th>Typical commission</th></tr><tr><td>Channel and listing management only</td><td>10–15%</td></tr><tr><td>Partial service</td><td>15–20%</td></tr><tr><td>Full management</td><td>20–30%</td></tr><tr><td>Luxury properties or remote areas</td><td>30% and above</td></tr></table><p>The most common model is a <strong>percentage of revenue</strong>; there are also fixed monthly fees or mixed formulas. Cleaning, photography and set-up costs are often charged separately.</p><h2>Gross or net? The detail that changes everything</h2><p>Two offers at “20%” can cost very different amounts. What matters is the <strong>basis of calculation</strong>:</p><ul><li><strong>on gross</strong>: the percentage applies to the full amount paid by the guest;</li><li><strong>on net</strong>: it applies after platform commissions and any cleaning fees are deducted.</li></ul><p>On a €1,000 booking with €155 Airbnb commission and €100 cleaning, 20% on gross is €200, on net €149. Always ask for it to be written into the contract.</p><h2>What to check before signing</h2><ol><li>The basis for the commission and which services are included.</li><li>Who pays for cleaning, linen and consumables.</li><li>Length of the contract, notice period and how to terminate.</li><li>Access to your accounts and ownership of the listings (and their reviews).</li><li>Reports: how often and with what data (revenue, occupancy, expenses).</li><li>Who collects payments and how tax matters are handled.</li></ol><h2>How we work</h2><p>At Living Stays we manage homes in Sicily to boutique-hotel standards: photos, listings in 5 languages, dynamic pricing, guests, cleaning and paperwork. We always start with a free, no-obligation assessment.</p><div class="srcs"><h4>Sources (in Italian)</h4><ul><li><a href="https://hello.pricelabs.co/it/blog/commissioni-property-manager-affitti-brevi/" target="_blank" rel="noopener">PriceLabs — Property manager commissions for short-term rentals (May 2026)</a></li><li><a href="https://www.smoobu.com/it/blog/aumento-costi-singoli-host-airbnb/" target="_blank" rel="noopener">Smoobu — Airbnb’s single 15.5% host fee</a></li></ul></div>'''),

 dict(it="airbnb-o-booking-dove-pubblicare", en="airbnb-or-booking-where-to-list", img="/img/p/kleos-1.webp", mins=5,
  title="Airbnb or Booking.com: where should you list your apartment?",
  desc="Airbnb (new single 15.5% host fee) and Booking.com commissions compared, differences in audience, and why the best strategy is to use several channels.",
  body='''<p class="lead">Airbnb and Booking.com are the two main channels for short-term rentals in Italy. Since 2026 their commissions have moved closer, but their audiences and the way they work are still different. Here is how to choose — and why the answer is often “both”.</p><h2>Commissions in 2026</h2><h3>Airbnb: the single host fee arrives</h3><p>Airbnb is moving all hosts to the <strong>host-only fee</strong> model: the whole commission, <strong>15.5%</strong> in most cases, is paid by the host, and guests no longer pay a separate service fee. For hosts in the European Economic Area, Italy included, the switch began on <strong>13 October 2026</strong>.</p><p>Before, the host paid about 3% and the guest paid 12% to 14% on top of the price. In practice, to keep the same net income, prices on Airbnb now need to be recalculated.</p><h3>Booking.com</h3><p>Booking.com charges a commission to the host only, usually between <strong>10% and 25%</strong>, averaging around <strong>15%</strong>. It is calculated on the total booking value, extras included, and invoiced monthly. Programmes that boost visibility (such as Preferred Partner or Genius discounts) usually involve extra costs or discounts.</p><h2>Audience and how they work</h2><table><tr><th></th><th>Airbnb</th><th>Booking.com</th></tr><tr><td>Audience</td><td>couples, families, longer stays, travellers looking for an “experience”</td><td>very international, last-minute bookings too, travellers used to hotels</td></tr><tr><td>Commission</td><td>15.5% host-only (EEA)</td><td>average ~15%, variable</td></tr><tr><td>Strength</td><td>well-presented listings and detailed reviews</td><td>huge traffic and visibility abroad</td></tr><tr><td>Handle with care</td><td>prices to realign with the new fee</td><td>cancellations, no-shows, payment terms</td></tr></table><h2>The strategy that works: several channels, one calendar</h2><p>Listing on both increases occupancy, especially in low season. To do it safely you need:</p><ul><li>a <strong>channel manager</strong> that syncs calendars and prices, to avoid double bookings;</li><li><strong>consistent prices</strong> that account for the different commissions;</li><li>a <strong>direct channel</strong> (website and WhatsApp) for returning guests, with no commission.</li></ul><p>That is what we do for the homes we manage: Airbnb and Booking.com in sync, plus direct bookings through our website.</p><div class="srcs"><h4>Sources (in Italian)</h4><ul><li><a href="https://www.smoobu.com/it/blog/aumento-costi-singoli-host-airbnb/" target="_blank" rel="noopener">Smoobu — Airbnb’s single 15.5% fee: what changes in 2026</a></li><li><a href="https://hello.pricelabs.co/it/blog/commissioni-booking-com/" target="_blank" rel="noopener">PriceLabs — Booking.com commissions (April 2026)</a></li><li><a href="https://quifinanza.it/lifestyle/travel-economy/affitti-brevi-tariffe-airbnb-aumento-2026/1008149/" target="_blank" rel="noopener">QuiFinanza — Airbnb raises host commissions from 13 October</a></li></ul></div>'''),
]
